static unsigned long decode_utf8(const unsigned char **cursor) {
  const unsigned char *p = *cursor;
  unsigned long cp;
  if (*p < 0x80) { *cursor = p + 1; return *p; }
  if ((*p & 0xe0) == 0xc0) {
    cp = ((unsigned long)(p[0] & 0x1f) << 6) | (p[1] & 0x3f);
    *cursor = p + 2; return cp;
  }
  cp = ((unsigned long)(p[0] & 0x0f) << 12) |
       ((unsigned long)(p[1] & 0x3f) << 6) | (p[2] & 0x3f);
  *cursor = p + 3; return cp;
}

void render_text_jp(unsigned short x, unsigned short y, const char *text) {
  const unsigned char *p = (const unsigned char *)text;
  while (*p) {
    unsigned long cp = decode_utf8(&p);
    unsigned int i;
    if (cp >= 0x20 && cp <= 0x7e) {
      char ascii[2]; ascii[0] = (char)cp; ascii[1] = 0;
      render_text(x, y + 2, ascii); x += 8; continue;
    }
    for (i = 0; i < sizeof(codepoints) / sizeof(codepoints[0]); ++i) {
      if (codepoints[i] == cp) {
        draw_glyph(x, y, 16, 16, 2, glyphs[i]); x += 16; break;
      }
    }
    if (i == sizeof(codepoints) / sizeof(codepoints[0])) x += 16;
  }
}

void render_text_jp_wrapped_clipped(unsigned short x, unsigned short y,
                                    unsigned short width, unsigned short bottom,
                                    const char *text) {
  const unsigned char *p = (const unsigned char *)text;
  unsigned short cx=x, cy=y;
  while (*p && cy < bottom) {
    const unsigned char *start=p; unsigned long cp=decode_utf8(&p);
    unsigned short advance=(cp>=0x20 && cp<=0x7e)?8:16;
    if (cp=='\n' || cx+advance>x+width) { cx=x; cy+=20; if(cp=='\n') continue; }
    { char one[5]; unsigned int n=(unsigned int)(p-start),i; for(i=0;i<n;i++) one[i]=start[i]; one[n]=0; render_text_jp(cx,cy,one); }
    cx+=advance;
  }
}

void render_text_jp_wrapped(unsigned short x, unsigned short y, unsigned short width,
                            const char *text) {
  render_text_jp_wrapped_clipped(x, y, width, 304, text);
}
